package com.smarthospital.controller;
import com.smarthospital.model.*;import com.smarthospital.util.*;import javax.servlet.*;import javax.servlet.http.*;import javax.servlet.annotation.*;import java.io.*;import java.sql.*;import java.util.*;
@WebServlet("/notifications") public class NotificationServlet extends HttpServlet{protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{User u=(User)req.getSession().getAttribute("user");try(Connection c=DB.getConnection()){List<Map<String,Object>>l=new ArrayList<>();try(PreparedStatement p=c.prepareStatement("SELECT notification_id,message,type,status,created_at FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 50")){p.setInt(1,u.id());ResultSet r=p.executeQuery();while(r.next()){Map<String,Object>m=new HashMap<>();for(int i=1;i<=5;i++)m.put("c"+i,r.getObject(i));l.add(m);}}req.setAttribute("rows",l);req.getRequestDispatcher("/notifications.jsp").forward(req,resp);}catch(Exception e){throw new ServletException(e);}}
 protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws IOException{User u=(User)req.getSession().getAttribute("user");try(Connection c=DB.getConnection();PreparedStatement p=c.prepareStatement("UPDATE notifications SET status='READ' WHERE notification_id=? AND user_id=?")){p.setInt(1,Integer.parseInt(req.getParameter("notification_id")));p.setInt(2,u.id());p.executeUpdate();resp.sendRedirect(req.getContextPath()+"/notifications");}catch(Exception e){resp.sendError(400,e.getMessage());}}
}
